class Solution {
public:
    string minInteger(string num, int k) {
        string res = num;
        int n = res.size();
        for (int i = 0; i < n && k > 0; ++i) {
            char min_digit = res[i];
            int min_pos = i;
            for (int j = i + 1; j < n && j - i <= k; ++j) {
                if (res[j] < min_digit) {
                    min_digit = res[j];
                    min_pos = j;
                    if (min_digit == '0') break;
                }
            }
            for (int j = min_pos; j > i; --j)
                swap(res[j], res[j - 1]);
            k -= (min_pos - i);
        }
        return res;
    }
};
